package common

import (
	"archive/tar"
	"bytes"
	"errors"
	"fmt"
	"io"
	"path"
	"strings"
)

// checksumFileName is regenerated by every export with a timestamp in it,
// and bkn-backend verifies it on import only when present. Keeping it would
// make every export look changed and turn stale after any edit in git.
const checksumFileName = "CHECKSUM"

// ReadBKNTar reads the regular files of a BKN tar, the format bkn-backend
// exports. Paths are normalised as bkn-backend does on import: leading "./"
// removed and cleaned. CHECKSUM is dropped. Entries that escape the archive
// root are refused.
func ReadBKNTar(data []byte) (map[string][]byte, error) {
	files := map[string][]byte{}
	tr := tar.NewReader(bytes.NewReader(data))
	for {
		header, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return files, nil
		}
		if err != nil {
			return nil, err
		}
		// Typeflag zero is the legacy regular-file marker.
		if header.Typeflag != tar.TypeReg && header.Typeflag != 0 {
			continue
		}
		name, err := normalizeTarPath(header.Name)
		if err != nil {
			return nil, err
		}
		if name == checksumFileName {
			continue
		}
		content, err := io.ReadAll(tr)
		if err != nil {
			return nil, err
		}
		files[name] = content
	}
}

func normalizeTarPath(name string) (string, error) {
	trimmed := name
	for strings.HasPrefix(trimmed, "./") {
		trimmed = strings.TrimPrefix(trimmed, "./")
	}
	cleaned := path.Clean(trimmed)
	if trimmed == "" || path.IsAbs(cleaned) || cleaned == "." || cleaned == ".." ||
		strings.HasPrefix(cleaned, "../") || strings.ContainsAny(name, "\\\x00") {
		return "", fmt.Errorf("tar entry %q escapes the archive root", name)
	}
	return cleaned, nil
}
